package net.mandomc.verification;
import java.nio.file.*;import java.util.*;import org.bukkit.*;import org.bukkit.block.*;import org.bukkit.plugin.java.JavaPlugin;import net.mandomc.bootstrap.MandoPlugin;import net.mandomc.gameplay.territory.*;
public final class HothCavesProbe extends JavaPlugin {
 World world;int checks;Path dir;Set<Long>chunks=new HashSet<>();record Tile(int x,int y,int z){}
 public void onEnable(){dir=getDataFolder().toPath();Bukkit.getScheduler().runTaskLater(this,()->{try{relight();}catch(Throwable t){fail(t);}},100);}
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}
 int[] ints(String s){return Arrays.stream(s.split(",")).mapToInt(Integer::parseInt).toArray();}
 long key(int x,int z){return((long)x<<32)|(z&0xffffffffL);}
 void fail(Throwable t){getLogger().log(java.util.logging.Level.SEVERE,"HOTH FAILED",t);try{Files.writeString(dir.resolve("FAILED.txt"),t.toString());}catch(Exception ignored){}Bukkit.shutdown();}
 void relight()throws Exception{
 world=Bukkit.getWorld(NamespacedKey.minecraft("hoth"));check(world!=null,"Hoth loaded");for(String line:Files.readAllLines(dir.resolve("expected.txt"))){int[] p=ints(line.split("\\|",2)[0]);chunks.add(key(Math.floorDiv(p[0],16),Math.floorDiv(p[2],16)));}
 Object level=world.getClass().getMethod("getHandle").invoke(world);Object cache=level.getClass().getMethod("getChunkSource").invoke(level);Object light=cache.getClass().getMethod("getLightEngine").invoke(cache);Class<?> status=Class.forName("net.minecraft.world.level.chunk.status.ChunkStatus");Object full=status.getField("FULL").get(null);Class<?> pos=Class.forName("net.minecraft.world.level.ChunkPos");var ctor=pos.getConstructor(int.class,int.class);List<Object>positions=new ArrayList<>();
 for(long k:chunks){int x=(int)(k>>32),z=(int)k;var c=world.getChunkAt(x,z);c.addPluginChunkTicket(this);Object h=c.getClass().getMethod("getHandle",status).invoke(c,full);h.getClass().getMethod("initializeLightSources").invoke(h);h.getClass().getMethod("setLightCorrect",boolean.class).invoke(h,true);positions.add(ctor.newInstance(x,z));}
 java.util.function.Consumer<Object> progress=c->{};java.util.function.IntConsumer done=n->Bukkit.getScheduler().runTaskLater(this,()->{try{verify();}catch(Throwable t){fail(t);}},40);light.getClass().getMethod("starlight$serverRelightChunks",Collection.class,java.util.function.Consumer.class,java.util.function.IntConsumer.class).invoke(light,positions,progress,done);
 }
 void verify()throws Exception{
 var main=(MandoPlugin)Bukkit.getPluginManager().getPlugin("MandoMC");var policy=Bukkit.getServicesManager().load(TerritoryService.class).policy();var atlas=policy.map("minecraft:hoth",0,0);var rows=Files.readAllLines(dir.resolve("atlas.txt"));check(atlas!=null,"Hoth atlas");int wild=0;
 for(int z=-16;z<=15;z++)for(int x=-16;x<=15;x++){char c=rows.get(z+16).charAt(x+16);check(atlas.zone(x,z)==c,"atlas cell");for(int y:List.of(-64,70,319)){var expected=c=='S'?TerritoryPolicy.Zone.SAFEZONE:c=='W'?TerritoryPolicy.Zone.WARZONE:TerritoryPolicy.Zone.WILDERNESS;check(policy.zone("minecraft:hoth",x*16,y,z*16)==expected,"full-height policy");}check(policy.wildernessChunk("minecraft:hoth",x,z)==(c=='.'),"claim eligibility");if(c=='.')wild++;}
 check(wild==681,"681 wilderness chunks");check(!policy.wildernessChunk("minecraft:hoth",16,0)&&!policy.wildernessChunk("minecraft:hoth",-17,0),"outside claims refused");check(world.getWorldBorder().getSize()==512&&world.getWorldBorder().getCenter().getX()==0&&world.getWorldBorder().getCenter().getZ()==0,"centered512border");
 check(main.worlds().resolve("Tatooine").getKey().toString().equals("minecraft:tatooine_review"),"official Tatooine alias");check(main.worlds().resolve("Mandalore").getKey().toString().equals("minecraft:mandalore_review"),"official Mandalore alias");check(main.worlds().resolve("TatooineReview")==main.worlds().resolve("Tatooine"),"hidden compatibility alias");check(main.worlds().names().stream().noneMatch(s->s.toLowerCase().contains("review")||s.toLowerCase().contains("legacy")),"no Review or legacy suggestions");check(main.warps().destination("tatooine").getWorld()==main.worlds().resolve("Tatooine"),"warp and official world agree");check(main.worlds().resolve("TatooineLegacy").getKey().toString().equals("minecraft:tatooine"),"legacy data retained");
 int ore=0;for(String line:Files.readAllLines(dir.resolve("expected.txt"))){var a=line.split("\\|",2);int[] p=ints(a[0]);var b=world.getBlockAt(p[0],p[1],p[2]);check(b.getBlockData().getAsString().equals(Bukkit.createBlockData("minecraft:"+a[1]).getAsString()),"cave state "+a[0]);if(a[1].startsWith("redstone_ore"))ore++;if(a[1].equals("air"))check(b.getLightFromSky()==0,"fully enclosed cave "+a[0]);}check(ore==1253,"new Electrum node count");
 Set<Tile>floors=new HashSet<>();for(String line:Files.readAllLines(dir.resolve("floors.txt"))){int[] p=ints(line);var b=world.getBlockAt(p[0],p[1],p[2]);check(!b.getCollisionShape().getBoundingBoxes().isEmpty(),"solid walking floor");check(b.getRelative(0,1,0).isPassable()&&b.getRelative(0,2,0).isPassable(),"two-block walking clearance");floors.add(new Tile(p[0],p[1],p[2]));}
 var anchors=Files.readAllLines(dir.resolve("anchors.txt"));int[] start=ints(anchors.getFirst().split("\\|",2)[1]);Tile first=new Tile(start[0],start[1],start[2]);Set<Tile>seen=new HashSet<>();seen.add(first);var q=new ArrayDeque<Tile>();q.add(first);
 while(!q.isEmpty()){var p=q.remove();for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}})for(int dy=-1;dy<=1;dy++){var n=new Tile(p.x+d[0],p.y+dy,p.z+d[1]);if(seen.contains(n)||!floors.contains(n))continue;if(dy>0&&!world.getBlockAt(p.x,p.y+3,p.z).isPassable())continue;if(dy<0&&!world.getBlockAt(n.x,n.y+3,n.z).isPassable())continue;seen.add(n);q.add(n);}}
 for(String a:anchors){int[] p=ints(a.split("\\|",2)[1]);check(seen.contains(new Tile(p[0],p[1],p[2])),"main room reachable "+a);}
 for(String line:Files.readAllLines(dir.resolve("lights.txt"))){int[] p=ints(line);var b=world.getBlockAt(p[0],p[1],p[2]);check(b.getType()==Material.GLOW_LICHEN,"lichen retained");check(b.getLightFromBlocks()>=7,"native cave light");}
 world.save();world.removePluginChunkTickets(this);String result=checks+" native assertions; all15 major rooms walkable,1253 Electrum,87S/256W/681wild,512border and official aliases/warp verified";Files.writeString(dir.resolve("PASSED.txt"),result);getLogger().info("HOTH PASSED "+result);
 }
}
